     */
    const val XOVER_BAND_BASE: Int = 20
    /**
     * Maximum preset slots.
     */
    const val MAX_PRESETS: Int = 10
    /**
     * Channel / preset name buffer size.
     */
    const val CHANNEL_NAME_LEN: Int = 32
    /**
     * Physical output pin slots (4 S/PDIF + 1 PDM on RP2350).
     */
    const val MAX_PHYSICAL_OUTPUTS: Int = 5
    /**
     * Master volume mute sentinel (true −∞).
     */
    const val MASTER_VOL_MUTE_DB: Float = -128.0f

    // ── dspi-core consts.rs ──
    /**
     * Bytes of a crossfeed pair map, one per stereo pair.
     */
    const val CROSSFEED_MAP_PAIRS: Int = 4
    /**
     * Number of psychoacoustic bass parameters.
     */
    const val PSYBASS_PARAM_COUNT: Int = 5
    /**
     * The device name or an input source name changed.
     */
    const val NOTIFY_NAMES: Int = 1 shl 8
    /**
     * The device went away.
     */
    const val NOTIFY_DISCONNECTED: Int = 1 shl 9
    /**
     * Status of an extension write the device stalled.
     */
    const val EXT_WRITE_REFUSED: Int = 0xFF
    /**
     * The state could not be re-read after retries: it may be out of date.
     */
    const val NOTIFY_STALE: Int = 1 shl 10
    /**
     * An input or output stream changed state (ADAT, I2S slave, ...).
     */
    const val NOTIFY_STREAMS: Int = 1 shl 11

    // ── firmware config.h (not in the core; FIRMWARE_CONSTS) ──
    /** Preset startup mode: load the specified default slot (macOS "Specified Default"). */
    const val PRESET_STARTUP_SPECIFIED: Int = 0
    /** Preset startup mode: load the last active slot (macOS "Last Used"). */
    const val PRESET_STARTUP_LAST_ACTIVE: Int = 1
}

